def checkout(cart, user, payment_method):
    # validate
    if not cart.items:
        raise ValueError('Cart is empty')
    for item in cart.items:
        if item.quantity <= 0:
            raise ValueError(f'Invalid quantity for {item.name}')
        if not item.in_stock:
            raise ValueError(f'{item.name} is out of stock')
    # discount
    subtotal = sum(i.price * i.quantity for i in cart.items)
    discount = 0
    if user.is_premium:
        discount = subtotal * 0.1
    if subtotal > 100:
        discount += 5
    total_before_tax = subtotal - discount
    # tax
    tax = total_before_tax * 0.08
    total = total_before_tax + tax
    # charge
    charge_result = payment_method.charge(total)
    if not charge_result.success:
        raise PaymentError(charge_result.error)
    # email
    send_email(user.email, 'Order confirmed', f'Your total was ${total:.2f}')
    return {'total': total, 'charge_id': charge_result.id}
